/**
 * QR generator helpers — Phase 8 (TQR-1).
 *
 * Pure, framework-free (architect spec §6 boundary rule): no React/Next/DOM
 * imports. Used by the internal `/tools/qr` page to turn a human label into
 * the placement URL that gets encoded in the printed QR (FR-1).
 */

export const MAX_PLACEMENT_CODE_LENGTH = 60;

/**
 * Turn a human label into a placement-code slug.
 * e.g. "Plot 13 Site Signage" → "plot-13-site-signage".
 * Falls back to "unknown" so the result always resolves (FR-4 safe).
 */
export function slugifyLabel(label: string): string {
  const slug = label
    .toLowerCase()
    .trim()
    .replace(/[_\s]+/g, "-")
    .replace(/[^a-z0-9-]/g, "")
    .replace(/-+/g, "-")
    .replace(/^-+|-+$/g, "")
    .slice(0, MAX_PLACEMENT_CODE_LENGTH);
  return slug || "unknown";
}

/** Join a canonical origin and code into `https://<host>/l/<code>` (FR-1). */
export function buildPlacementUrl(siteUrl: string, code: string): string {
  const origin = siteUrl.replace(/\/+$/, "");
  return `${origin}/l/${code}`;
}
