"use client";

import { useEffect, useState } from "react";
import Image from "next/image";

import { toolsQr } from "@/data/content/tools-qr";
import { buildPlacementUrl, slugifyLabel } from "@/lib/qr";

interface QrGeneratorProps {
  siteUrl: string;
  activePlacements: { code: string; label: string }[];
}

/** Copy helper: Clipboard API → legacy textarea fallback (same chain as FallbackPanel). */
async function copyText(text: string): Promise<boolean> {
  try {
    if (navigator.clipboard && window.isSecureContext) {
      await navigator.clipboard.writeText(text);
      return true;
    }
  } catch {
    /* fall through */
  }
  try {
    const textarea = document.createElement("textarea");
    textarea.value = text;
    textarea.setAttribute("readonly", "");
    textarea.style.position = "fixed";
    textarea.style.opacity = "0";
    document.body.appendChild(textarea);
    textarea.select();
    const ok = document.execCommand("copy");
    document.body.removeChild(textarea);
    return ok;
  } catch {
    return false;
  }
}

/**
 * Internal QR generator (Phase 8, TQR-2).
 * Client-only: QR encoding runs in the browser via a dynamic `qrcode` import
 * so the funnel routes (`/`, `/l/*`) never pay for it (Q15).
 */
export function QrGenerator({ siteUrl, activePlacements }: QrGeneratorProps) {
  const [label, setLabel] = useState(activePlacements[0]?.label ?? "");
  const [qrDataUrl, setQrDataUrl] = useState("");
  const [copyStatus, setCopyStatus] = useState("");

  const code = slugifyLabel(label);
  const url = buildPlacementUrl(siteUrl, code);
  const isKnown = activePlacements.some((p) => p.code === code);

  useEffect(() => {
    let cancelled = false;
    // NOTE: old QR stays visible until the new one resolves — avoids a
    // synchronous setState-in-effect while the URL changes.
    import("qrcode")
      .then((m) => m.toDataURL(url, { width: 256, margin: 2 }))
      .then((dataUrl) => {
        if (!cancelled) setQrDataUrl(dataUrl);
      })
      .catch(() => {
        if (!cancelled) setQrDataUrl("");
      });
    return () => {
      cancelled = true;
    };
  }, [url]);

  const handleCopy = async () => {
    const ok = await copyText(url);
    setCopyStatus(ok ? toolsQr.copiedLabel : toolsQr.copyFailedLabel);
  };

  return (
    <div className="mx-auto w-full max-w-3xl flex-1 px-4 pb-28 pt-10 sm:px-6">
      <h1 className="text-2xl font-semibold tracking-tight">{toolsQr.title}</h1>
      <p className="mt-2 text-sm text-zinc-600 dark:text-zinc-400">
        {toolsQr.intro}
      </p>

      <label
        htmlFor="qr-label"
        className="mt-6 block text-sm font-medium text-zinc-900 dark:text-zinc-100"
      >
        {toolsQr.labelLabel}
      </label>
      <input
        id="qr-label"
        type="text"
        value={label}
        onChange={(e) => setLabel(e.target.value)}
        placeholder={toolsQr.labelPlaceholder}
        data-qr-input
        className="mt-2 w-full rounded-xl border border-zinc-300 px-4 py-3 text-base dark:border-zinc-700 dark:bg-zinc-900"
      />

      <dl className="mt-6 space-y-3 text-sm">
        <div>
          <dt className="font-medium text-zinc-500">{toolsQr.codeLabel}</dt>
          <dd data-qr-code className="font-mono font-semibold">
            {code}
          </dd>
        </div>
        <div>
          <dt className="font-medium text-zinc-500">{toolsQr.urlLabel}</dt>
          <dd data-qr-url className="break-all font-mono text-xs">
            {url}
          </dd>
        </div>
        <div>
          <dd
            data-qr-badge
            data-known={isKnown ? "true" : "false"}
            className="inline-block rounded-full bg-zinc-100 px-3 py-1 text-xs font-medium dark:bg-zinc-800"
          >
            {isKnown ? toolsQr.knownBadge : toolsQr.newBadge}
          </dd>
        </div>
      </dl>

      <div className="mt-6">
        {qrDataUrl ? (
          <Image
            src={qrDataUrl}
            alt={toolsQr.qrAlt}
            width={256}
            height={256}
            unoptimized
            data-qr-image
            className="h-64 w-64 rounded-xl border border-zinc-200 dark:border-zinc-800"
          />
        ) : (
          <p className="text-sm text-zinc-500">{toolsQr.generatingLabel}</p>
        )}
      </div>

      <div className="mt-6 flex flex-col gap-3 sm:flex-row">
        {qrDataUrl ? (
          <a
            href={qrDataUrl}
            download={`qr-${code}.png`}
            data-qr-download
            className="inline-flex items-center justify-center rounded-xl bg-emerald-700 px-4 py-3 text-sm font-semibold text-white hover:bg-emerald-800"
          >
            {toolsQr.downloadLabel}
          </a>
        ) : null}
        <button
          type="button"
          onClick={handleCopy}
          data-qr-copy
          className="inline-flex items-center justify-center rounded-xl border border-zinc-300 px-4 py-3 text-sm font-semibold hover:bg-zinc-50 dark:border-zinc-700 dark:hover:bg-zinc-800"
        >
          {toolsQr.copyUrlLabel}
        </button>
      </div>
      <p aria-live="polite" className="mt-2 min-h-5 text-sm text-emerald-700">
        {copyStatus}
      </p>

      <h2 className="mt-10 text-lg font-semibold">{toolsQr.existingTitle}</h2>
      <ul className="mt-3 space-y-2">
        {activePlacements.map((p) => (
          <li
            key={p.code}
            className="flex items-center justify-between gap-3 rounded-xl border border-zinc-200 px-4 py-3 text-sm dark:border-zinc-800"
          >
            <span>
              <span className="font-medium">{p.label}</span>{" "}
              <span className="font-mono text-xs text-zinc-500">{p.code}</span>
            </span>
            <button
              type="button"
              onClick={() => setLabel(p.label)}
              data-qr-use={p.code}
              className="rounded-lg border border-zinc-300 px-3 py-1.5 text-xs font-semibold hover:bg-zinc-50 dark:border-zinc-700 dark:hover:bg-zinc-800"
            >
              {toolsQr.useLabel}
            </button>
          </li>
        ))}
      </ul>
    </div>
  );
}
